def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    result = v1 * v2

    return {
        "value": result,
        "trace": {
            "v1": v1,
            "v2": v2,
            "result": result,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "dollars"
            }
        }
    }
